const { camelCase } = require('../../camelCase');

describe('camelCase input guard', () => {
  it('throws the documented Error for null', () => {
    let caught;
    try {
      camelCase(null);
    } catch (e) {
      caught = e;
    }
    expect(caught).toBeDefined();
    expect(caught).not.toBeInstanceOf(TypeError);
    expect(caught.message).toBe('The object must be an object');
  });

  it.each([['x'], [5], [undefined], [true]])('still throws the documented Error for %p', (value) => {
    expect(() => camelCase(value)).toThrow('The object must be an object');
  });
});

describe('camelCase conversion is unchanged', () => {
  it('converts snake_case and kebab-case keys and keeps values', () => {
    expect(camelCase({ snake_case: 1, 'kebab-case': 2, plain: 3 })).toEqual({ snakeCase: 1, kebabCase: 2, plain: 3 });
  });

  it('does not mutate its input and returns a new object', () => {
    const input = { a_b: 1 };
    const out = camelCase(input);
    expect(input).toEqual({ a_b: 1 });
    expect(out).not.toBe(input);
  });

  it('returns an empty object for an empty object', () => {
    expect(camelCase({})).toEqual({});
  });
});

